import{_ as a,a as t,b as r}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as i,o as n,c as o,a3 as s}from"./chunks/framework.D1iekJsc.js";const w=JSON.parse('{"title":"Create with AI","description":"MiniTavern generates a character card from a description and an optional reference image using a configured model. Edit, keep fields, then create.","frontmatter":{"title":"Create with AI","description":"MiniTavern generates a character card from a description and an optional reference image using a configured model. Edit, keep fields, then create.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Create with AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern generates a character card from a description and an optional reference image using a configured model. Edit, keep fields, then create."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/ai-create"}]]},"headers":[],"relativePath":"en/manual/ai-create.md","filePath":"en/manual/ai-create.md","lastUpdated":1791861929000}'),l={name:"en/manual/ai-create.md"};function c(d,e,h,g,p,m){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="create-with-ai" tabindex="-1">Create with AI <a class="header-anchor" href="#create-with-ai" aria-label="Permalink to &quot;Create with AI&quot;">​</a></h1><p>Path: bottom <strong>Characters</strong> → <strong>Create / Import</strong> → <strong>Create with AI</strong>.</p><p>Set up a <a href="./model-link">model link</a> and pass Test first. With no usable model, generation stays unavailable and the page points you to setup.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="Create with AI entry"><figcaption>1 · Create / Import → Create with AI</figcaption></figure><figure class="shot-step"><img src="'+t+'" alt="Description and reference image"><figcaption>2 · Pick a model and write a description</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="Preview and create the character"><figcaption>3 · Preview, then create</figcaption></figure></div><h2 id="generate" tabindex="-1">Generate <a class="header-anchor" href="#generate" aria-label="Permalink to &quot;Generate&quot;">​</a></h2><ol><li><strong>Model</strong>: pick one of the model links you already configured. The default link is selected first; you can switch.</li><li><strong>Description</strong> (required): say what character you want.</li><li><strong>Reference image</strong> (optional): tap the image to enlarge it; the close icon at the top right removes it. With an image, the selected model must support images. If it does not, switch models or remove the image.</li><li>Tap <strong>Generate</strong>. The button shows “Generating”. Model, description, and reference image cannot be changed while it runs.</li></ol><p>The reference image lets the model see the character. After the first successful generation it is filled in as the <strong>character image</strong>. The model does not draw a new picture. Without a reference image, choose an image on the preview before you can create the card.</p><p>If generation fails, a message appears. <strong>View details</strong> shows the reason. Cancelling does not show a failure message.</p><h2 id="preview-and-keep" tabindex="-1">Preview and Keep <a class="header-anchor" href="#preview-and-keep" aria-label="Permalink to &quot;Preview and Keep&quot;">​</a></h2><p>A successful generation opens <strong>Preview character</strong>. The generate page itself does not show the card.</p><ul><li>Name, description, tags, personality, greetings, world book, and the rest can be edited directly.</li><li>Each AI field, and the whole <strong>world book</strong>, has <strong>Keep</strong>. When it is on, the next generation leaves that item unchanged. Editing text does not turn Keep on by itself.</li><li><strong>Regenerate</strong> opens a text box first. Write what should change, or leave it empty to generate again from the original description. Fields and the world book with Keep on stay as they are. If everything is kept, no request is sent.</li><li>While generating, <strong>Regenerate</strong> shows a loading state and <strong>Create Character</strong> becomes cancel.</li><li><strong>Create Character</strong> shows a loading notice, then a success notice. Image, name, and description are required.</li><li>Characters based on anime, film, or other existing works can include a world book. After you create the card, that setting stays on the card and is also copied into a world book chats can use. See <a href="./lorebook">Lorebook</a>.</li><li>Leaving the preview before creating discards the draft and returns to the generate page. The reference image stays there.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./chara-card">Character cards</a>: import, edit, start chats</li><li><a href="./model-link">Model link</a>: configure the model used to generate</li></ul>',14)])])}const b=i(l,[["render",c]]);export{w as __pageData,b as default};
